CREATE OR REPLACE FUNCTION nexus.purge_trash(older_than interval)
RETURNS bigint
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = nexus, public
AS $$
DECLARE
    v_tenant       TEXT;
    v_count        BIGINT;
    v_chunk_count  BIGINT;
    v_chunk_sample jsonb;
BEGIN
    v_tenant := current_setting('nexus.tenant', true);
    IF v_tenant IS NULL OR v_tenant = '' THEN
        RAISE EXCEPTION
            'purge_trash: nexus.tenant GUC must be set to a non-empty tenant scope. '
            'Cross-tenant purge is not permitted. Set the nexus.tenant configuration '
            'parameter before calling purge_trash.';
    END IF;

    SET CONSTRAINTS fk_catalog_chunks_chunk DEFERRED;

    WITH del AS (
        DELETE FROM nexus.chunks c
        WHERE c.tenant_id = v_tenant
          AND EXISTS (
              SELECT 1
                FROM nexus.catalog_document_chunks m
               WHERE m.tenant_id = c.tenant_id
                 AND m.chash      = c.chash
          )
          AND NOT EXISTS (
              SELECT 1
                FROM nexus.catalog_document_chunks m
                JOIN nexus.catalog_documents d
                  ON d.tenant_id = m.tenant_id
                 AND d.tumbler   = m.doc_id
               WHERE m.tenant_id  = c.tenant_id
                 AND m.chash       = c.chash
                 AND (d.deleted_at IS NULL OR d.deleted_at > NOW() - older_than)
          )
        RETURNING c.chash
    ),
    counted AS (SELECT count(*) AS n FROM del),
    sampled AS (
        SELECT jsonb_agg(encode(chash, 'hex')) AS s
          FROM (SELECT chash FROM del LIMIT 5000) lim
    )
    SELECT counted.n, sampled.s INTO v_chunk_count, v_chunk_sample FROM counted, sampled;

    DELETE FROM nexus.catalog_documents
     WHERE tenant_id  = v_tenant
       AND deleted_at IS NOT NULL
       AND deleted_at <= NOW() - older_than;

    GET DIAGNOSTICS v_count = ROW_COUNT;

    IF v_chunk_count > 0 OR v_count > 0 THEN
        INSERT INTO nexus.gc_audit
            (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details)
        VALUES (
            v_tenant, 'purge_trash', '', 'engine', false, COALESCE(v_chunk_count, 0),
            COALESCE(v_chunk_sample, '[]'::jsonb),
            jsonb_build_object(
                'documents_purged', v_count,
                'chunks_swept', COALESCE(v_chunk_count, 0),
                'older_than', older_than::text
            ) || CASE WHEN COALESCE(v_chunk_count, 0) > 5000
                      THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000)
                      ELSE '{}'::jsonb END
        );
    END IF;

    RETURN v_count;
END;
$$
